   private static void q(VertexConsumer vc, Matrix4f m, Matrix3f nm, int light, float s, int a,
                         float x0, float y0, float z0, float u0, float v0,
                         float x1, float y1, float z1, float u1, float v1,
                         float x2, float y2, float z2, float u2, float v2,
                         float x3, float y3, float z3, float u3, float v3,
                         float nx, float ny, float nz) {
      v(vc, m, nm, light, a, x0 * s, y0 * s, z0 * s, u0, v0, nx, ny, nz);
      v(vc, m, nm, light, a, x1 * s, y1 * s, z1 * s, u1, v1, nx, ny, nz);
      v(vc, m, nm, light, a, x2 * s, y2 * s, z2 * s, u2, v2, nx, ny, nz);
      v(vc, m, nm, light, a, x3 * s, y3 * s, z3 * s, u3, v3, nx, ny, nz);
   }

   private static void v(VertexConsumer vc, Matrix4f m, Matrix3f nm, int light, int alpha,
                         float x, float y, float z, float u, float vv,
                         float nx, float ny, float nz) {
      vc.vertex(m, x, y, z)
         .color(255, 255, 255, alpha)
         .uv(u, vv)
         .overlayCoords(OverlayTexture.NO_OVERLAY)
         .uv2(light)
         .normal(nm, nx, ny, nz)
         .endVertex();
   }
